            Membership.level(Membership.points(owner, false, false)));
        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
            OWNER_SEQ.incrementAndGet(), owner.getId(), memberId,
            Membership.level(Membership.points(owner, false, false)));
